# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BİR PEYGAMBER TANIYORUM: HZ. DAVUD (AS)</text>\n  <rect x="20" y="46" width="210" height="194" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Peygamberliği ve Zebur</text>\n  <text x="32" y="96" font-size="11.5" fill="#1e3a8a">• İsrailoğullarına gönderilen</text>\n  <text x="32" y="114" font-size="11.5" fill="#1e3a8a">  peygamber ve hükümdardır.</text>\n  <text x="32" y="138" font-size="11.5" fill="#1e3a8a">• Kudüs\'ü başkent yapmıştır.</text>\n  <text x="32" y="162" font-size="11.5" fill="#1e3a8a">• Kendisine dört büyük ilahi</text>\n  <text x="32" y="180" font-size="11.5" fill="#1e3a8a">  vahiyden الزَّبُور (Zebur) verildi.</text>\n  <text x="125" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Gür ve Lâtif Ses Mucizesi</text>\n\n  <rect x="245" y="46" width="210" height="194" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Mucizeleri ve El Emeği</text>\n  <text x="257" y="96" font-size="11.5" fill="#14532d">• Demiri ateş ve çekiç olmadan</text>\n  <text x="257" y="114" font-size="11.5" fill="#14532d">  balmumu gibi bükerdi.</text>\n  <text x="257" y="138" font-size="11.5" fill="#14532d">• Kendi el emeğiyle zırh yapıp</text>\n  <text x="257" y="156" font-size="11.5" fill="#14532d">  satarak geçimini sağlardı.</text>\n  <text x="257" y="180" font-size="11.5" fill="#14532d">• Dağlar ve kuşlar onunla</text>\n  <text x="257" y="198" font-size="11.5" fill="#14532d">  birlikte Allah\'ı tesbih ederdi.</text>\n  <text x="350" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Helal Kazanç ve Çalışkanlık</text>\n\n  <rect x="470" y="46" width="210" height="194" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="575" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">Adaleti ve Davud Orucu</text>\n  <text x="482" y="96" font-size="11.5" fill="#713f12">• İnsanlar arasında adaletle</text>\n  <text x="482" y="114" font-size="11.5" fill="#713f12">  ve hakkaniyetle hükmetti.</text>\n  <text x="482" y="138" font-size="11.5" fill="#713f12">• En faziletli nafile oruç:</text>\n  <text x="482" y="156" font-size="11.5" fill="#713f12">  Bir gün oruç, bir gün iftar.</text>\n  <text x="482" y="180" font-size="11.5" fill="#713f12">• Kendisine hikmet ve hakkı</text>\n  <text x="482" y="198" font-size="11.5" fill="#713f12">  batıldan ayıran hitabet verildi.</text>\n  <text x="575" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">Adalet · İbadet · Sabır</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FİL OLAYI (571) VE FİL SURESİNİN ÖZELLİKLERİ</text>\n  <rect x="25" y="48" width="315" height="192" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Fil Olayı (Vak\'atü\'l-Fîl)</text>\n  <text x="40" y="98" font-size="11.5" fill="#831843">• Yemen Valisi Ebrehe, San\'a şehrinde</text>\n  <text x="40" y="116" font-size="11.5" fill="#831843">  büyük bir mabet yaptırdı.</text>\n  <text x="40" y="138" font-size="11.5" fill="#831843">• Arapların Kâbe\'yi ziyaret etmesini</text>\n  <text x="40" y="156" font-size="11.5" fill="#831843">  engellemek için Kâbe\'yi yıkmak istedi.</text>\n  <text x="40" y="178" font-size="11.5" fill="#831843">• En önde «Mahmûd» adlı filin yer aldığı</text>\n  <text x="40" y="196" font-size="11.5" fill="#831843">  büyük bir orduyla Mekke\'ye yürüdü.</text>\n  <text x="182" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">Hz. Muhammed\'in (sav) Doğduğu Yıl: 571</text>\n\n  <rect x="360" y="48" width="315" height="192" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">İlahi Yardım ve Helak</text>\n  <text x="375" y="98" font-size="11.5" fill="#581c87">• Abdülmuttalib: «Kâbe\'nin sahibi Allah\'tır,</text>\n  <text x="375" y="116" font-size="11.5" fill="#581c87">  Beyt\'ini (evini) O koruyacaktır.»</text>\n  <text x="375" y="138" font-size="11.5" fill="#581c87">• Yüce Allah sürü sürü kuşlar (طَيْرًا أَبَابِيلَ)</text>\n  <text x="375" y="156" font-size="11.5" fill="#581c87">  ve pişkin tuğladan taşlar (سِجِّيلٍ) gönderdi.</text>\n  <text x="375" y="178" font-size="11.5" fill="#581c87">• Ebrehe\'nin ordusu yenilmiş ekin yaprağı</text>\n  <text x="375" y="196" font-size="11.5" fill="#581c87">  gibi (كََعَصْفٍ مَأْكُولٍ) darmadağın edildi.</text>\n  <text x="517" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#581c87">Mekke Dönemi · 5 Ayet · 105. Sure</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FİL SURESİNİN OKUNUŞU VE ANLAMI (سُورَةُ الْفِيلِ)</text>\n  <rect x="20" y="42" width="660" height="202" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="350" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#0e7490">بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ — Rahmân ve Rahîm olan Allah\'ın adıyla</text>\n  <text x="350" y="92" text-anchor="middle" font-size="11.5" fill="#155e75">1. أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ الْفِيلِ (Rabbinin fil sahiplerine ne yaptığını görmedin mi?)</text>\n  <text x="350" y="118" text-anchor="middle" font-size="11.5" fill="#155e75">2. أَلَمْ يَجْعَلْ كَيْدَهُمْ فِي تَضْلِيلٍ (Onların tuzaklarını boşa çıkarmadı mı?)</text>\n  <text x="350" y="144" text-anchor="middle" font-size="11.5" fill="#155e75">3. وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ (Üzerlerine sürü sürü kuşlar gönderdi.)</text>\n  <text x="350" y="170" text-anchor="middle" font-size="11.5" fill="#155e75">4. تَرْمِيهِمْ بِحِجَارَةٍ مِنْ سِجِّيلٍ (Onlara pişkin tuğladan yapılmış taşlar atıyorlardı.)</text>\n  <text x="350" y="196" text-anchor="middle" font-size="11.5" fill="#155e75">5. فَجَعَلَهُمْ كَعَصْفٍ مَأْكُولٍ (Böylece Allah onları yenilmiş ekin yaprağı gibi kıldı.)</text>\n  <text x="350" y="226" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">Ana Mesaj: Yüce Allah\'ın kudreti her şeyin üstündedir; kibir ve zulüm sahiplerinin tuzağı boşa çıkar.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
